<?php
declare(strict_types=1);ob_start();session_start();require dirname(__DIR__,2).'/config/config.php';
function bursar_dashboard_json(int $status,array $data):never{http_response_code($status);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(ob_get_level())ob_clean();echo json_encode($data,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);exit;}
if(!signed_in())bursar_dashboard_json(401,['ok'=>false,'message'=>'Your session expired. Sign in again.']);require_sign_in();if(!empty($_SESSION['must_change_password']))bursar_dashboard_json(403,['ok'=>false,'message'=>'Change your password before continuing.']);if(($_SESSION['role']??'')!=='bursar')bursar_dashboard_json(403,['ok'=>false,'message'=>'This dashboard is for Bursar accounts.']);$uid=(int)$_SESSION['user_id'];$school=filter_var($_GET['school_id']??null,FILTER_VALIDATE_INT);if(!$school)bursar_dashboard_json(422,['ok'=>false,'message'=>'Choose a school.']);
try{$db=db();$q=$db->prepare('SELECT 1 FROM school_memberships WHERE user_id=? AND school_id=?');$q->execute([$uid,$school]);if(!$q->fetchColumn())bursar_dashboard_json(403,['ok'=>false,'message'=>'That school is outside your access.']);$q=$db->prepare("SELECT COUNT(*) FROM pupils WHERE school_id=? AND status='active'");$q->execute([$school]);$activePupils=(int)$q->fetchColumn();$q=$db->prepare("SELECT COUNT(*) pupils_with_arrears,COALESCE(SUM(balance),0) total_arrears FROM (SELECT pupil_id,SUM(CASE WHEN entry_type IN ('charge','payment_reversal','discount_reversal') THEN amount WHEN entry_type IN ('payment','charge_reversal','discount') THEN -amount ELSE 0 END) balance FROM school_fee_ledger WHERE school_id=? GROUP BY pupil_id HAVING balance>0) arrears");$q->execute([$school]);$arrears=$q->fetch()?:['pupils_with_arrears'=>0,'total_arrears'=>0];$q=$db->prepare("SELECT COALESCE(SUM(CASE WHEN entry_type='payment' THEN amount WHEN entry_type='payment_reversal' THEN -amount ELSE 0 END),0) collected,COUNT(CASE WHEN entry_type IN ('payment','payment_reversal') THEN 1 END) payment_entries FROM school_fee_ledger WHERE school_id=? AND created_at>=DATE_FORMAT(CURRENT_DATE,'%Y-%m-01')");$q->execute([$school]);$month=$q->fetch()?:['collected'=>0,'payment_entries'=>0];$q=$db->prepare("SELECT COUNT(*) FROM fee_structures WHERE school_id=? AND status='draft'");$q->execute([$school]);$draftStructures=(int)$q->fetchColumn();$q=$db->prepare('SELECT l.id,l.entry_type,l.description,l.amount,l.created_at,l.academic_year,l.term,l.payment_method,l.reference,p.admission_number,p.first_name,p.middle_name,p.last_name,p.class_level FROM school_fee_ledger l JOIN pupils p ON p.id=l.pupil_id AND p.school_id=l.school_id WHERE l.school_id=? ORDER BY l.created_at DESC,l.id DESC LIMIT 10');$q->execute([$school]);$entries=$q->fetchAll();bursar_dashboard_json(200,['ok'=>true,'data'=>['active_pupils'=>$activePupils,'pupils_with_arrears'=>(int)$arrears['pupils_with_arrears'],'total_arrears'=>(float)$arrears['total_arrears'],'month_net_payments'=>(float)$month['collected'],'month_payment_entries'=>(int)$month['payment_entries'],'draft_fee_structures'=>$draftStructures,'recent_entries'=>$entries,'month_label'=>date('F Y')]]);}catch(Throwable $e){error_log('Bursar dashboard request failed: '.$e->getMessage());bursar_dashboard_json(500,['ok'=>false,'message'=>'Finance dashboard data could not be loaded.']);}
